const source = $('Build Weekly Brief').first().json;
const validated = $('Validate AI Report').first().json;

const summary = validated.validatedReport;

const maxDescription = 4000;
const description = summary.length > maxDescription
  ? summary.slice(0, maxDescription - 40) + '\n\n_(truncated for Discord)_'
  : summary;

return [{
  json: {
    webhookUrl: source.discordWebhookUrl,
    body: {
      username: 'Weekly GitHub Dev Summary',
      embeds: [{
        title: `Weekly Dev Summary — ${source.repository}`,
        description,
        fields: [
          { name: 'Commits', value: String(source.counts.commits), inline: true },
          { name: 'Closed issues', value: String(source.counts.closedIssues), inline: true },
          { name: 'Merged PRs', value: String(source.counts.mergedPRs), inline: true },
          { name: 'Language', value: source.language, inline: true }
        ],
        footer: { text: 'Generated by n8n AI Agent using Claude Sonnet 4 via OpenRouter' },
        timestamp: new Date().toISOString()
      }]
    }
  }
}];

const cfg = $json;
const problems = [];

if (!cfg.repo || !/^[^/\s]+\/[^/\s]+$/.test(String(cfg.repo))) {
  problems.push('repo must use owner/repo format');
}

const language = String(cfg.language || '').toUpperCase();
if (!['EN', 'FR'].includes(language)) {
  problems.push('language must be EN or FR');
}

const daysBack = Number(cfg.daysBack);
if (!Number.isFinite(daysBack) || daysBack <= 0 || daysBack > 31) {
  problems.push('daysBack must be a number between 1 and 31');
}

if (cfg.enableSuccessDelivery === true) {
  if (!cfg.discordWebhookUrl || !String(cfg.discordWebhookUrl).startsWith('https://discord.com/api/webhooks/')) {
    problems.push('discordWebhookUrl must be configured when enableSuccessDelivery is true');
  }
}

if (problems.length) {
  throw new Error(`Preflight validation failed: ${problems.join('; ')}`);
}

return [{
  json: {
    ...cfg,
    language,
    daysBack
  }
}];

const commitRows = $('Fetch Commits').all().map(i => i.json);
const issueResponse = $('Fetch Closed Issues').first().json;
const prResponse = $('Fetch Merged PRs').first().json;

const commitPayload =
  (commitRows.length === 1 && Array.isArray(commitRows[0]))
    ? commitRows[0]
    : commitRows;

const problems = [];

if (!Array.isArray(commitPayload)) {
  problems.push('GitHub commits response is not an array');
} else {
  const malformed = commitPayload.find(c => !c || typeof c !== 'object' || !('sha' in c) || !c.commit);
  if (malformed) problems.push('GitHub commits response contains an unexpected item shape');
}

if (!issueResponse || !Array.isArray(issueResponse.items)) {
  problems.push('GitHub closed-issues search response is missing items[]');
}

if (!prResponse || !Array.isArray(prResponse.items)) {
  problems.push('GitHub merged-PR search response is missing items[]');
}

if (problems.length) {
  throw new Error(`GitHub contract validation failed: ${problems.join('; ')}`);
}

return [{
  json: {
    githubContractValid: true,
    commitCount: commitPayload.length,
    closedIssueCount: issueResponse.items.length,
    mergedPrCount: prResponse.items.length
  }
}];

const agent = $('AI Agent - Weekly Summary').first().json;
const output = agent.output ?? agent.text ?? agent.response;

if (typeof output !== 'string' || output.trim().length < 80) {
  throw new Error('AI output validation failed: report text was missing or too short');
}

const requiredHeadings = [
  'Development Activity',
  'Issues and Pull Requests',
  'Notable Patterns',
  'What to Watch Next'
];

const missing = requiredHeadings.filter(h => !output.includes(h));

if (missing.length) {
  throw new Error(`AI output validation failed: missing section(s): ${missing.join(', ')}`);
}

return [{
  json: {
    validatedReport: output,
    reportLength: output.length
  }
}];
